import { createClient } from 'supabase';
import Papa from 'papaparse';

const BASE='https://raw.githubusercontent.com/olbauday/FPL-Core-Insights/main/data/2026-2027/By%20Tournament/Friendlies/GW0';
const num=(v:any)=>v===undefined||v===null||v===''?null:Number(v);
const int=(v:any)=>{const n=num(v);return n===null?null:Math.round(n)};
const bool=(v:any)=>String(v).toLowerCase()==='true';
async function csv(name:string){const r=await fetch(`${BASE}/${name}`);if(!r.ok)throw new Error(`${name}: ${r.status}`);const text=await r.text();const p=Papa.parse(text,{header:true,skipEmptyLines:true});return p.data as any[];}
function chunks<T>(a:T[],n=250){const out:T[][]=[];for(let i=0;i<a.length;i+=n)out.push(a.slice(i,i+n));return out;}
Deno.serve(async()=>{
 const keys=JSON.parse(Deno.env.get('SUPABASE_SECRET_KEYS')||'{}'); const key=keys.default||Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!; const sb=createClient(Deno.env.get('SUPABASE_URL')!,key,{auth:{persistSession:false}}); let runId:any=null;
 try{
  const {data:run,error:re}=await sb.from('source_sync_runs').insert({source:'fpl_core_insights_friendlies',status:'running'}).select('id').single();if(re)throw re;runId=run.id;
  const [ms,ps]=await Promise.all([csv('matches.csv'),csv('playermatchstats.csv')]);
  const {data:teams,error:te}=await sb.from('teams').select('id,team_code');if(te)throw te;const tm=new Map((teams||[]).map((t:any)=>[Number(t.team_code),t.id]));
  const matchRows=ms.map((m:any)=>({source:'fpl_core_insights',source_match_id:m.match_id,competition:'friendly',gameweek:0,kickoff_time:m.kickoff_time||null,home_team_id:tm.get(Number(m.home_team))||null,away_team_id:tm.get(Number(m.away_team))||null,home_score:int(m.home_score),away_score:int(m.away_score),finished:bool(m.finished),home_xg:num(m.home_expected_goals_xg),away_xg:num(m.away_expected_goals_xg),home_xgot:num(m.home_xg_on_target_xgot),away_xgot:num(m.away_xg_on_target_xgot),home_big_chances:int(m.home_big_chances),away_big_chances:int(m.away_big_chances),home_possession:num(m.home_possession),away_possession:num(m.away_possession),raw:m}));
  for(const c of chunks(matchRows)){const {error}=await sb.from('matches').upsert(c,{onConflict:'source,source_match_id'});if(error)throw error;}
  const {data:dbm,error:me}=await sb.from('matches').select('id,source_match_id').eq('source','fpl_core_insights').eq('competition','friendly');if(me)throw me;const mm=new Map((dbm||[]).map((m:any)=>[m.source_match_id,m.id]));
  const {data:players,error:pe}=await sb.from('players').select('id,fpl_player_id');if(pe)throw pe;const pm=new Map((players||[]).map((p:any)=>[Number(p.fpl_player_id),p.id]));
  let skipped=0;const rows:any[]=[];for(const p of ps){const player=pm.get(Number(p.player_id)),match=mm.get(p.match_id);if(!player||!match){skipped++;continue;}const mins=int(p.minutes_played);const cbit=[p.clearances,p.blocks,p.interceptions,p.tackles].reduce((s:any,v:any)=>s+(num(v)||0),0);rows.push({source:'fpl_core_insights',source_player_id:int(p.player_id),source_match_id:p.match_id,player_id:player,match_id:match,minutes:mins,started:int(p.start_min)===0,formation:null,role:null,xg:num(p.xg),xa:num(p.xa),xgi:(num(p.xg)||0)+(num(p.xa)||0),xgot:num(p.xgot),shots:int(p.total_shots),shots_on_target:int(p.shots_on_target),big_chances:null,big_chances_missed:int(p.big_chances_missed),touches_box:int(p.touches_opposition_box),goals:int(p.goals),assists:int(p.assists),clearances:int(p.clearances),blocks:int(p.blocks),interceptions:int(p.interceptions),tackles:int(p.tackles),recoveries:int(p.recoveries),cbit:Math.round(cbit),cbirt:Math.round(cbit+(num(p.recoveries)||0)),raw:p});}
  for(const c of chunks(rows,200)){const {error}=await sb.from('player_matches').upsert(c,{onConflict:'source,source_player_id,source_match_id'});if(error)throw error;}
  await sb.from('source_sync_runs').update({finished_at:new Date().toISOString(),status:'success',rows_inserted:matchRows.length+rows.length,metadata:{matches:matchRows.length,player_matches:rows.length,skipped_unmapped:skipped,season:'2026-2027',competition:'friendlies'}}).eq('id',runId);return Response.json({ok:true,matches:matchRows.length,player_matches:rows.length,skipped_unmapped:skipped});
 }catch(e){const msg=e instanceof Error?e.message:String(e);if(runId)await sb.from('source_sync_runs').update({finished_at:new Date().toISOString(),status:'error',error:msg}).eq('id',runId);return Response.json({ok:false,error:msg},{status:500})}
});
